import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

// Mock classes for compilation
class ImageDescriptor {}
class Image {}
class Display {}

public class MyClass {
    // This will not match because it's a ConcurrentHashMap constructor, not a HashMap.
    private Map<ImageDescriptor, Image> fRegistry = Collections.synchronizedMap(new java.util.concurrent.ConcurrentHashMap<ImageDescriptor, Image>(10));
    private Display fDisplay;

    public void someMethod() {
        // This will not match because it's a ConcurrentHashMap.
        Map<String, String> concurrentMap = new java.util.concurrent.ConcurrentHashMap<String, String>();
        System.out.println(fRegistry.size());
        System.out.println(concurrentMap.isEmpty());
    }
}

